import{j as e,a as n,f as o,L as a}from"./main-DtrNWOuI.js";import{C as s}from"./chevron-down-DyqaT6Fo.js";import"./index-Yx4Ou-hz.js";const r=[{question:"What can TicketDepart help me with?",answer:"A travel specialist can help you compare domestic and international flight options, review routes and travel dates, compare economy options, discuss fare conditions, and explore available next steps for your trip."},{question:"How much does it cost to call?",answer:"Calling is free and there is no obligation to book. You can ask questions, compare options, and decide afterward. If you do book, any service fee is disclosed clearly before you confirm."},{question:"Can you help with international flights?",answer:"Yes. International travel is a large part of what we do, including long-haul routes, connections through major hubs, and itineraries that cross multiple regions. We can also talk through entry requirements and realistic connection times."},{question:"What is a multi-city itinerary?",answer:"A multi-city itinerary has more than one stopover or direction change — for example, flying into one city and out of another, or visiting several cities in sequence. We sequence the segments so the routing and pricing work together."},{question:"Can you help book a flight with a pet?",answer:"A specialist can discuss your route, pet type, airline pet policies, carrier requirements, and documentation questions. Pet acceptance, capacity, and fees depend on the airline, aircraft, route, and applicable rules."},{question:"Can you help book a flight with an infant?",answer:"Yes. Discuss the infant's age, lap-infant or separate-seat arrangements, bassinet requests, and itinerary details. Airline rules and availability must be confirmed for the specific flight."},{question:"What if my plans change after booking?",answer:"Call us. We will review the fare conditions on your ticket, explain what changes are allowed and any costs involved, and rebook or restructure the trip where possible."},{question:"Do you charge for changes or cancellations?",answer:"Any airline change or cancellation fees come from the fare rules of your ticket, and we explain those before you book. Where we apply a service fee for handling a change, we tell you the amount before we proceed."},{question:"How do I get my ticket after booking?",answer:"Once your booking is confirmed, we send your confirmation and itinerary to the email address you provide. Your ticket number and flight details will be included so you can check in directly with the airline."}];function u(){return e.jsxs(n,{tone:"paper",ocid:"home.faq_section","aria-labelledby":"home-faq-heading",children:[e.jsx(o,{id:"home-faq-heading",eyebrow:"Questions",title:"Frequently asked questions",description:"Straight answers about how our flight booking service works."}),e.jsx("div",{className:"mt-12 grid gap-3 lg:grid-cols-2 lg:gap-x-8",children:r.map((i,t)=>e.jsxs("details",{"data-ocid":`home.faq_item.${t+1}`,className:"group rounded-xl border border-border bg-card px-5 py-4 shadow-subtle transition-smooth open:shadow-elevated",children:[e.jsxs("summary",{className:"flex min-h-11 cursor-pointer list-none items-start justify-between gap-4 text-left text-base font-semibold leading-snug marker:content-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",children:[e.jsx("span",{children:i.question}),e.jsx(s,{"aria-hidden":"true",className:"mt-0.5 size-5 shrink-0 text-accent transition-transform duration-300 group-open:rotate-180"})]}),e.jsx("p",{className:"mt-3 text-sm leading-relaxed text-muted-foreground",children:i.answer})]},i.question))}),e.jsxs("p",{className:"mt-10 text-sm leading-relaxed text-muted-foreground",children:["Still have a question?"," ",e.jsx(a,{to:"/contact/","data-ocid":"home.faq_contact_link",className:"font-medium text-primary underline underline-offset-4 transition-smooth hover:text-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",children:"Contact our travel desk"})," ","and a specialist will answer it."]})]})}export{u as HomeFaq};
